def _install(sqlite_source, mysql_source, event_guard):
    sqlite = op.get_bind().dialect.name == "sqlite"
    op.execute("DROP TRIGGER IF EXISTS shared_weekly_source_insert_guard")
    op.execute("DROP TRIGGER IF EXISTS mapping_event_insert")
    for name, table, condition, error in (
        (
            "shared_weekly_source_insert_guard",
            "shared_weekly_source",
            sqlite_source if sqlite else mysql_source,
            "shared_source_publish_invalid",
        ),
        (
            "mapping_event_insert",
            "identity_mapping_event",
            event_guard,
            "mapping_conflict",
        ),
    ):
        if sqlite:
            op.execute(
                f"CREATE TRIGGER {name} BEFORE INSERT ON {table} WHEN {condition} BEGIN SELECT RAISE(ABORT, '{error}'); END"
            )
        else:
            op.execute(
                f"CREATE TRIGGER {name} BEFORE INSERT ON {table} FOR EACH ROW BEGIN IF {condition} THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='{error}'; END IF; END"
            )


